 CREATE TABLE IF NOT EXISTS public.mcp_conversation_notification_counts (
@@
   PRIMARY KEY (organization_id, user_id, client_identity, conversation_id)
 );
+
+-- notification_targets is the single durable chokepoint for inbox unread
+-- state. Maintain the conversation projection there so every caller (REST,
+-- SDK, and future writers) gets the same cross-replica behavior without
+-- duplicating counter logic in each service method.
+CREATE OR REPLACE FUNCTION public.sync_mcp_conversation_notification_count()
+RETURNS trigger
+LANGUAGE plpgsql
+AS $sync$
+DECLARE
+  attribution public.notification_mcp_conversations%ROWTYPE;
+  delta integer := 0;
+  target_event_id bigint;
+  target_user_id text;
+BEGIN
+  IF TG_OP = 'INSERT' THEN
+    target_event_id := NEW.event_id;
+    target_user_id := NEW.user_id;
+    IF NEW.read_at IS NULL THEN delta := 1; END IF;
+  ELSIF TG_OP = 'UPDATE' THEN
+    target_event_id := NEW.event_id;
+    target_user_id := NEW.user_id;
+    IF OLD.read_at IS NULL AND NEW.read_at IS NOT NULL THEN
+      delta := -1;
+    ELSIF OLD.read_at IS NOT NULL AND NEW.read_at IS NULL THEN
+      delta := 1;
+    END IF;
+  ELSE
+    target_event_id := OLD.event_id;
+    target_user_id := OLD.user_id;
+    IF OLD.read_at IS NULL THEN delta := -1; END IF;
+  END IF;
+
+  IF delta = 0 THEN
+    IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
+  END IF;
+
+  SELECT * INTO attribution
+  FROM public.notification_mcp_conversations
+  WHERE notification_event_id = target_event_id;
+  IF NOT FOUND THEN
+    IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
+  END IF;
+
+  IF delta > 0 THEN
+    INSERT INTO public.mcp_conversation_notification_counts (
+      organization_id, user_id, client_identity, conversation_id,
+      unread_count, updated_at
+    ) VALUES (
+      attribution.organization_id, target_user_id,
+      attribution.client_identity, attribution.conversation_id, 1, now()
+    )
+    ON CONFLICT (organization_id, user_id, client_identity, conversation_id)
+    DO UPDATE SET
+      unread_count = public.mcp_conversation_notification_counts.unread_count + 1,
+      updated_at = now();
+  ELSE
+    UPDATE public.mcp_conversation_notification_counts
+    SET unread_count = unread_count - 1, updated_at = now()
+    WHERE organization_id = attribution.organization_id
+      AND user_id = target_user_id
+      AND client_identity = attribution.client_identity
+      AND conversation_id = attribution.conversation_id
+      AND unread_count > 0;
+    IF NOT FOUND THEN
+      RAISE EXCEPTION 'MCP conversation unread counter is inconsistent';
+    END IF;
+  END IF;
+
+  IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
+END
+$sync$;
+
+DROP TRIGGER IF EXISTS notification_targets_mcp_conversation_count
+  ON public.notification_targets;
+CREATE TRIGGER notification_targets_mcp_conversation_count
+AFTER INSERT OR DELETE OR UPDATE OF read_at
+ON public.notification_targets
+FOR EACH ROW
+EXECUTE FUNCTION public.sync_mcp_conversation_notification_count();
